def solve(text):
    def program():
        n = int(input())
        carp = [['#']]
        for k in range(1, n + 1):
            tmp = []
            for _ in range(3):
                for c in carp[k - 1]:
                    tmp.append(c * 3)
            tmp = list(map(list, tmp))
            cen = 3 ** k // 2
            diff = 3 ** (k - 1) // 2
            for i in range(3 ** k):
                for j in range(3 ** k):
                    if cen - diff <= i <= cen + diff and cen - diff <= j <= cen + diff:
                        tmp[i][j] = '.'
            carp.append(tmp)
        for c in carp[n]:
            print(''.join(c))
    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

