def solve(text):
    def program():
        import sys
        sys.setrecursionlimit(10 ** 7)

        def input():
            return sys.stdin.readline().rstrip()

        def main():
            N, M = map(int, input().split())
            B = [list(map(int, input().split())) for _ in range(N)]
            for i in range(N):
                for j in range(M):
